import re
from dataclasses import dataclass, field
from typing import Optional

# Release headings: "## [2.4.0] - 2024-05-02" (dated) or "## [Unreleased]" (undated).
HEADING = re.compile(r"^## \[(?P<version>[^\]]+)\](?: - (?P<date>\d{4}-\d{2}-\d{2}))?\s*$")

# Maintainer notes. May span several lines; never rendered.
COMMENT = re.compile(r"<!--.*?-->", re.DOTALL)

# Stand-in for a removed comment. NUL never appears in changelog text.
_MARK = "\x00"


@dataclass
class Release:
    version: str
    date: Optional[str]
    body: list = field(default_factory=list)


def strip_comments(text):
    """Return the lines of ``text`` with HTML comments removed.

    A comment is replaced in place, so text after a multi-line comment's
    closing ``-->`` stays on the line where the comment began. Lines that
    had a comment removed lose their trailing whitespace.
    """
    lines = []
    for line in COMMENT.sub(_MARK, text).splitlines():
        if _MARK in line:
            line = line.replace(_MARK, "").rstrip()
        lines.append(line)
    return lines


def parse_changelog(text):
    releases = []
    current = None
    for line in strip_comments(text):
        if line.startswith("## "):
            match = HEADING.match(line)
            if match is None:
                raise ValueError(f"malformed release heading: {line!r}")
            current = Release(match.group("version"), match.group("date"))
            releases.append(current)
        elif current is not None:
            current.body.append(line)
    return releases


def _tidy(lines):
    """Collapse runs of blank lines to one and trim blank lines at both ends."""
    out = []
    for line in lines:
        if line.strip() == "":
            if out and out[-1] == "":
                continue
            line = ""
        out.append(line)
    while out and out[0] == "":
        out.pop(0)
    while out and out[-1] == "":
        out.pop()
    return out


def render_release(text, version):
    for release in parse_changelog(text):
        if release.version == version:
            title = f"{release.version} ({release.date})" if release.date else "Unreleased"
            lines = [f"# {title}"]
            body = _tidy(release.body)
            if body:
                lines += [""] + body
            return "\n".join(lines) + "\n"
    raise LookupError(version)

